exports.handler = async function handler(event) {
  try {
    // routes/bestsellers.js:18-22
    const params = {
      TableName: BESTSELLERS_TABLE,
    };

    const data = await docClient.send(new ScanCommand(params));

    // routes/bestsellers.js:24-28
    const sorted = (data.Items || [])
      .sort((a, b) => (b.salesCount || 0) - (a.salesCount || 0))
      .slice(0, 20)
      .map((item) => item.bookId);

    return shared.response(200, sorted);
  } catch (error) {
    // routes/bestsellers.js:30-33 -- the monolith swallowed the read failure and still
    // answered 200 with an empty list (GAP-14 / D-33); keep it, do not turn it into a 500.
    console.error('Error in GET /bestsellers:', error);
    return shared.response(200, []);
  }
};
