// Table name comes only from this function's environment_variables (blueprint, D-39).
const BOOKS_TABLE = process.env.BOOKS_TABLE;

exports.handler = async function handler(event) {
  try {
    // REST proxy integration puts the `{id}` path parameter here; keep it a string.
    const id = ((event && event.pathParameters) || {}).id;

    const data = await docClient.send(new GetCommand({
      TableName: BOOKS_TABLE,
      Key: { id: id },
    }));

    if (data.Item) {
      return shared.response(200, data.Item);
    }
    return shared.errorResponse(404, 'Book not found');
  } catch (error) {
    console.error('Error in GET /books/:id:', error);
    return shared.fromException(error);
  }
};
