                            "messageAttributes": {}, "md5OfBody": hashlib.md5(body.encode()).hexdigest(),
                            "eventSource": "aws:sqs", "eventSourceARN": f"arn:aws:sqs:{REGION}:{ACCOUNT}:{queue}", "awsRegion": REGION})
