/**
 * [R4] The items ("table|key") one message will read or write, computed with the
 * SAME builders the handler uses (mergeQuantities / transactionChunks), so the
 * schedule cannot drift from the requests actually sent. `[]` when the message is
 * skipped before any DynamoDB call (unparsable body, no `orderId`, nothing the
 * monolith's ADD would have accepted): such a message touches no item at all.
 */
function recordItemKeys(record) {
  let orderId;
  let books;
  try {
    const payload = JSON.parse(record.body);
    orderId = payload.orderId;
    books = payload.books;
  } catch (parseError) {
    return [];
  }
  if (!orderId || !Array.isArray(books)) {
    return [];
  }
  const merged = mergeQuantities(books);
  if (merged.size === 0) {
    return [];
  }
  const keys = [];
  for (const chunk of transactionChunks(orderId, merged)) {
    for (const item of chunk) {
      const spec = item.Put || item.Update;      // this chunk's marker, then one ADD per book
      const key = item.Put ? { pk: spec.Item.pk } : spec.Key;   // key attributes only
      keys.push(`${spec.TableName}|${JSON.stringify(key)}`);
    }
  }
  return keys;
}

/**
 * [R4] A message goes one wave after the latest earlier message it shares an
 * item with: messages of one wave touch disjoint items, and every item still
 * sees the messages in batch order.
 */
function scheduleWaves(records, keysOf) {
  const lastWave = new Map();
  const waves = [];
  for (const record of records) {
    const keys = keysOf(record);
    let wave = 0;
    for (const key of keys) if (lastWave.has(key)) wave = Math.max(wave, lastWave.get(key) + 1);
    for (const key of keys) lastWave.set(key, wave);
    (waves[wave] = waves[wave] || []).push(record);
  }
  return waves;
}

exports.handler = async function handler(event) {
  const records = (event && event.Records) || [];
  const failures = [];

  const handleRecord = async (record) => {   // was: for (const record of records) {
    let orderId;
    let books;
    try {
      const payload = JSON.parse(record.body);
      orderId = payload.orderId;
      books = payload.books;
      if (!orderId) {
        throw new Error('missing orderId');
      }
      if (!Array.isArray(books)) {
        throw new Error('missing or invalid books');
      }
    } catch (parseError) {
      // D-3: the monolith swallowed its background failures, so an unparsable message is
      // logged and skipped -- and NOT reported as a failure (that would spin it to the DLQ
      // for something the monolith would never have retried).
      console.error(`${CONSUMER}: skipping malformed message ${record.messageId}:`, parseError);
      return;
    }

    if (books.length === 0) {
      // routes/orders.js -> utils/bestsellers.js:41-43: an empty list was a no-op.
      console.log(`${CONSUMER}: order ${orderId} has no books, nothing to add`);
      return;
    }

    const outcome = await applyMessage(orderId, books);
    console.log(`${CONSUMER}: order ${orderId} -> ${outcome}`);
    if (outcome === 'failed') {
      // Failure policy (b): report it so SQS redelivers (idempotency makes that safe),
      // then DLQ after maxReceiveCount=3. Never swallow a transient failure.
      failures.push({ itemIdentifier: record.messageId });
    }
  };                                         // was: }

  // [R4] Waves run one after another; the messages of one wave run at the same
  // time and touch pairwise-disjoint items (recordItemKeys / scheduleWaves).
  for (const wave of scheduleWaves(records, recordItemKeys)) {
    await Promise.allSettled(wave.map(handleRecord));
  }

  // Batch order, as the sequential loop reported them.
  const order = new Map(records.map((record, index) => [record.messageId, index]));
  failures.sort((x, y) => order.get(x.itemIdentifier) - order.get(y.itemIdentifier));
  return { batchItemFailures: failures };
};

